package com.spinfit.bike.ui;
import android.app.*;import android.content.*;import android.os.Bundle;import android.text.InputType;import android.view.*;import android.widget.*;import com.spinfit.bike.app.*;
public final class SettingsActivity extends Activity{
 private Settings s;private EditText ftp,rmax,scale;private Switch auto;
 @Override protected void onCreate(Bundle b){super.onCreate(b);BikeSession.get().init(this);s=new Settings(this);LinearLayout root=Ui.root(this);root.addView(Ui.topBar(this,"训练设置",this::finish));root.addView(Ui.eyebrow(this,"YOUR PERSONAL BASELINE"));root.addView(Ui.title(this,"适合自己，才是好训练。"));root.addView(Ui.sub(this,"训练参数只影响之后开始的课程。进行中的骑行可在训练页调整阻力。"));Ui.gap(this,root,24);
  LinearLayout c=Ui.card(this);ftp=field(c,"FTP 功能阈值功率","仅用于换算参考功率目标 · 未知时先按体感骑行",s.ftpW(),50,500,"W");rmax=field(c,"单车阻力上限","与单车刻度保持一致，实际支持范围由设备决定",s.resistanceMax(),8,100,"档");Ui.gap(this,c,20);auto=new Switch(this);auto.setText("课程自动阻力");auto.setTextColor(Ui.TEXT);auto.setTextSize(16);auto.setMinHeight(Ui.dp(this,52));auto.setChecked(s.autoResistance());auto.setThumbTintList(android.content.res.ColorStateList.valueOf(Ui.ACCENT));c.addView(auto);c.addView(Ui.sub(this,"支持控阻的单车按课程阶段调整参考档位；自由骑行默认手动。"));Ui.add(this,root,c,20);
  LinearLayout d=Ui.card(this);d.addView(Ui.tv(this,"演示模式",17,Ui.TEXT,true));Ui.gap(this,d,6);scale=field(d,"演示时间倍率","仅影响模拟训练，真实骑行始终按正常时间记录",Math.round(s.timeScale()),1,60,"倍");Ui.add(this,root,d,20);
  Button save=Ui.primary(this,"保存设置");save.setOnClickListener(v->{Integer f=number(ftp,50,500),r=number(rmax,8,100),x=number(scale,1,60);if(f==null||r==null||x==null)return;s.setFtpW(f);s.setResistanceMax(r);s.setTimeScale(x);s.setAutoResistance(auto.isChecked());Toast.makeText(this,"设置已保存",Toast.LENGTH_SHORT).show();finish();});root.addView(save);Ui.gap(this,root,20);root.addView(Ui.sub(this,"训练记录仅保存在本机。正常关闭或更新应用会保留记录，卸载应用会删除本地记录。"));Ui.screen(this,root,null);
 }
 private EditText field(LinearLayout parent,String label,String hint,int value,int min,int max,String unit){Ui.gap(this,parent,16);parent.addView(Ui.tv(this,label,15,Ui.TEXT,true));Ui.gap(this,parent,8);parent.addView(Ui.sub(this,hint));Ui.gap(this,parent,10);LinearLayout row=Ui.row(this);EditText edit=new EditText(this);edit.setText(""+value);edit.setTextSize(22);edit.setTextColor(Ui.TEXT);edit.setSingleLine(true);edit.setSelectAllOnFocus(true);edit.setInputType(InputType.TYPE_CLASS_NUMBER);edit.setContentDescription(label+"，范围 "+min+" 到 "+max);edit.setPadding(Ui.dp(this,14),Ui.dp(this,12),Ui.dp(this,14),Ui.dp(this,12));Ui.surface(edit,Ui.BG,12);Ui.weight(row,edit);TextView u=Ui.sub(this,"  "+unit);row.addView(u);parent.addView(row);return edit;}
 private Integer number(EditText e,int min,int max){try{int n=Integer.parseInt(e.getText().toString());if(n>=min&&n<=max)return n;}catch(Exception x){}e.setError("请输入 "+min+"–"+max+" 之间的整数");e.requestFocus();return null;}
}
